To ensure the package validator fails closed when input files are malformed or have shape failures, we should validate the parsed file shape and record critical diagnostics when required fields or schemas are missing. This aligns with our defensive programming and fail-closed validation rules.

```javascript
function loadInputs(root, paths, diagnostics) {
  const packet = safeReadJson(root, paths.packetInputIn, "figureasset_vlm_candidate_packet_input", diagnostics);
  if (packet && (!packet.schema_version || !Array.isArray(packet.rows))) {
    diagnostics.push({
      code: "malformed_input_shape",
      role: "figureasset_vlm_candidate_packet_input",
      path: paths.packetInputIn,
      required: true,
      reason: "Input packet is missing schema_version or rows array",
      severity: "critical",
    });
  }
  const priorityQueue = safeReadJson(root, paths.priorityQueueIn, "visual_usage_figureasset_priority_queue", diagnostics);
  if (priorityQueue && (!priorityQueue.schema_version || !Array.isArray(priorityQueue.rows))) {
    diagnostics.push({
      code: "malformed_input_shape",
      role: "visual_usage_figureasset_priority_queue",
      path: paths.priorityQueueIn,
      required: true,
      reason: "Priority queue is missing schema_version or rows array",
      severity: "critical",
    });
  }
  const authorizationReceipt = safeReadJson(root, paths.authorizationReceiptIn, "figureasset_vlm_no_auth_receipt", diagnostics);
  if (authorizationReceipt && !authorizationReceipt.schema_version) {
    diagnostics.push({
      code: "malformed_input_shape",
      role: "figureasset_vlm_no_auth_receipt",
      path: paths.authorizationReceiptIn,
      required: true,
      reason: "Authorization receipt is missing schema_version",
      severity: "critical",
    });
  }
  const checkpoint = safeReadJson(root, paths.checkpointIn, "figureasset_vlm_harness_checkpoint", diagnostics);
  if (checkpoint && !checkpoint.schema_version) {
    diagnostics.push({
      code: "malformed_input_shape",
      role: "figureasset_vlm_harness_checkpoint",
      path: paths.checkpointIn,
      required: true,
      reason: "Checkpoint is missing schema_version",
      severity: "critical",
    });
  }

  return {
    packet: packet ?? {},
    priorityQueue: priorityQueue ?? {},
    authorizationReceipt: authorizationReceipt ?? {},
    checkpoint: checkpoint ?? {},
  };
}
```

